#!/usr/bin/env node
/**
 * dataset:check-urls
 * ==================
 * Every external URL in data/problems.json that is marked
 * `urlDerivedFromTitle` was generated by slugifying the problem title. That is
 * right for the overwhelming majority of LeetCode problems, but it is a
 * derivation, not a fact. This script actually requests each URL and reports
 * which ones do not resolve, so you can fix them before publishing.
 *
 *   npm run dataset:check-urls                 check everything
 *   npm run dataset:check-urls -- --derived    only the slug-derived ones
 *   npm run dataset:check-urls -- --limit 50   first 50 only
 *   npm run dataset:check-urls -- --concurrency 4
 *   npm run dataset:check-urls -- --out report.json
 *
 * Note: coding sites rate-limit and sometimes block automated requests, so a
 * non-200 here is a prompt to look, not proof the link is dead. Open the
 * failures in a browser before editing data/source/roadmap.mjs.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_DIR = resolve(__dirname, '..', 'data');

function arg(name, fallback) {
  const i = process.argv.indexOf(`--${name}`);
  return i === -1 ? fallback : process.argv[i + 1];
}
const onlyDerived = process.argv.includes('--derived');
const limit = Number(arg('limit', '0')) || 0;
const concurrency = Math.max(1, Number(arg('concurrency', '5')));
const outFile = arg('out', null);
const timeoutMs = Number(arg('timeout', '15000'));

const problems = JSON.parse(readFileSync(resolve(DATA_DIR, 'problems.json'), 'utf8'));

let queue = onlyDerived ? problems.filter((p) => p.urlDerivedFromTitle) : problems;
if (limit) queue = queue.slice(0, limit);

const results = [];
let done = 0;

async function probe(p) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    // HEAD is cheapest, but several coding sites reject it, so fall back to a
    // ranged GET that pulls only the first kilobyte.
    let res = await fetch(p.externalUrl, {
      method: 'HEAD',
      redirect: 'follow',
      signal: controller.signal,
      headers: { 'user-agent': 'AlgoLadder-link-check/1.0' },
    });
    if (res.status === 405 || res.status === 403 || res.status === 501) {
      res = await fetch(p.externalUrl, {
        method: 'GET',
        redirect: 'follow',
        signal: controller.signal,
        headers: { 'user-agent': 'AlgoLadder-link-check/1.0', range: 'bytes=0-1024' },
      });
    }
    return { id: p.id, title: p.title, url: p.externalUrl, status: res.status, ok: res.ok };
  } catch (err) {
    return {
      id: p.id,
      title: p.title,
      url: p.externalUrl,
      status: 0,
      ok: false,
      error: err?.name === 'AbortError' ? 'timeout' : String(err?.message ?? err),
    };
  } finally {
    clearTimeout(timer);
  }
}

async function worker(iterator) {
  for (const p of iterator) {
    const r = await probe(p);
    results.push(r);
    done += 1;
    if (!r.ok) {
      console.log(`  FAIL ${String(r.status).padStart(3)}  ${r.title}\n        ${r.url}${r.error ? `  (${r.error})` : ''}`);
    }
    if (done % 25 === 0) console.log(`  ... checked ${done}/${queue.length}`);
  }
}

const iterator = queue[Symbol.iterator]();

console.log(`\n  Checking ${queue.length} URLs with concurrency ${concurrency}...\n`);

await Promise.all(Array.from({ length: concurrency }, () => worker(iterator)));

const failures = results.filter((r) => !r.ok);

console.log('');
console.log(`  checked   ${results.length}`);
console.log(`  ok        ${results.length - failures.length}`);
console.log(`  failed    ${failures.length}`);
console.log('');

if (outFile) {
  writeFileSync(resolve(process.cwd(), outFile), JSON.stringify({ results, failures }, null, 2));
  console.log(`  report written to ${outFile}\n`);
}

if (failures.length) {
  console.log('  Fix each failure by adding a link override to the title in');
  console.log('  data/source/roadmap.mjs, then re-run `npm run dataset:build`:');
  console.log('      Title@lc:correct-leetcode-slug|...');
  console.log('      Title@gfg:correct-gfg-path|...');
  console.log('      Title@url:https://full.url/here|...\n');
}

// Link rot is not a reason to fail the build — report and exit clean.
process.exit(0);
